//! Federated continual evidence-surveillance interoperability gateway.
//!
//! Atlas feature: `AFA-obligation-P01-F24`. The gateway validates a caller-supplied evidence
//! stream, preserves all uncertainty and negative evidence, and emits only a digest-only,
//! policy-approved summary. It does not retrieve sources, infer biology, or make clinical
//! decisions.

use bioprism_foundation::{AuthorityRequirement,AutonomyTier,CapabilityManifest,Determinism,Effect,EvidenceReference,EvidenceState,ProvenanceLink,ResearchSurface,TypedPort,TypedResearchArtifact,PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID:&str="AFA-obligation-P01-F24";
pub const CONTRACT_VERSION:&str="obligation-federated-evidence-interoperability-gateway/1.0";
pub const INPUT_SCHEMA:&str="EvidenceFeed4@1";
pub const OUTPUT_SCHEMA:&str="QualifiedEvidenceSet6@1";
const CONTENT_TYPE:&str="application/vnd.aurora.qualified-evidence-set-6+json";

#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]
pub struct EvidenceObservation { pub evidence_id:String,pub source_id:String,pub study_id:String,pub modality:String,pub scope:String,pub relevance_milli:u16,pub freshness_milli:u16,pub state:EvidenceState,pub semantic_digest:ContentHash,pub artifact_digest:ContentHash,pub provenance_digest:ContentHash,pub replay_identity:ContentHash,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub negative_result:bool,pub local_data:bool,pub permitted:bool }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]
pub struct EvidenceFeed { pub request_id:String,pub federation_id:String,pub institution_id:String,pub endpoint:String,pub purpose:String,pub semantic_profile:String,pub required_study_order:Vec<String>,pub required_modality_order:Vec<String>,pub observations:Vec<EvidenceObservation>,pub replay_identity:ContentHash,pub policy_allow:bool,pub protected_closure:bool,pub signed_approval:bool,pub endpoint_approved:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub budget:u64,pub max_budget:u64,pub adversarial_events:Vec<String>,pub boundary:String }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]
pub struct QualifiedEvidenceSet { pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub federation_id:String,pub institution_id:String,pub endpoint:String,pub purpose:String,pub semantic_profile:String,pub disposition:String,pub evidence_order:Vec<String>,pub ranked_order:Vec<String>,pub admitted_order:Vec<String>,pub unresolved_order:Vec<String>,pub blocked_order:Vec<String>,pub missing_study_order:Vec<String>,pub missing_modality_order:Vec<String>,pub omission_order:Vec<String>,pub uncertainty_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub adversarial_event_order:Vec<String>,pub study_digest_order:Vec<ContentHash>,pub artifact_digest_order:Vec<ContentHash>,pub replay_identity:ContentHash,pub set_digest:ContentHash,pub artifact:TypedResearchArtifact,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String }
#[derive(Debug,Error,Clone,PartialEq,Eq)]
pub enum EvidenceGatewayError { #[error("invalid evidence gateway request: {0}")] Invalid(String), #[error("evidence gateway artifact failed: {0}")] Artifact(String) }
fn invalid(v:impl Into<String>)->EvidenceGatewayError{EvidenceGatewayError::Invalid(v.into())}
fn canonical(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
fn digest(v:&ContentHash)->bool{v.as_str().len()==64}

pub fn evidence_gateway_manifest()->CapabilityManifest{CapabilityManifest{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),capability_id:FEATURE_ID.into(),version:CONTRACT_VERSION.into(),owner_crate:"obligation".into(),consumers:["computational biologist".into(),"federation operator".into(),"evidence steward".into()].into(),behavior:"integrates typed evidence feeds into a deterministic qualified-evidence set with endpoint, provenance, locality, and policy gates".into(),value:"allows consortia to exchange permitted evidence summaries while retaining stale, unknown, contradicted, omitted, negative, and denied states".into(),inputs:vec![TypedPort{name:"evidence_feed".into(),schema:INPUT_SCHEMA.into(),required:true}],outputs:vec![TypedPort{name:"qualified_evidence_set".into(),schema:OUTPUT_SCHEMA.into(),required:true}],effects:[Effect::ReadLocalData,Effect::ExecuteLocalComputation,Effect::FederationExport,Effect::WriteLocalArtifact].into(),permissions:["connect:approved-endpoints".into()].into(),determinism:Determinism::ByteStable,evidence:vec![EvidenceReference{source_id:"mcp-2025-06-18".into(),state:EvidenceState::Supported,locator:Some("https://modelcontextprotocol.io/specification/2025-06-18/basic/index".into())},EvidenceReference{source_id:"ga4gh-wes".into(),state:EvidenceState::Supported,locator:Some("https://ga4gh.github.io/workflow-execution-service-schemas/docs/".into())}],authority_requirements:vec![AuthorityRequirement{role:"federation evidence steward".into(),reason:"approved endpoint and purpose-bound artifact exchange require institutional authorization".into()}],autonomy_tier:AutonomyTier::A2,surfaces:[ResearchSurface::Api,ResearchSurface::Protocol,ResearchSurface::Sdk,ResearchSurface::Ui,ResearchSurface::Policy,ResearchSurface::Operator].into(),boundary:PRECLINICAL_BOUNDARY.into()}}

impl QualifiedEvidenceSet{pub fn validate(&self)->Result<(),EvidenceGatewayError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.federation_id.trim().is_empty()||self.institution_id.trim().is_empty()||self.endpoint.trim().is_empty()||self.purpose.trim().is_empty()||self.semantic_profile.trim().is_empty()||!matches!(self.disposition.as_str(),"qualified"|"unresolved"|"blocked")||self.evidence_order.is_empty()||self.ranked_order.len()!=self.evidence_order.len()||self.effect_receipts.is_empty(){return Err(invalid("evidence set identity, locality, ranking, disposition, or effects are incomplete"));}for v in [&self.evidence_order,&self.admitted_order,&self.unresolved_order,&self.blocked_order,&self.missing_study_order,&self.missing_modality_order,&self.omission_order,&self.uncertainty_order,&self.negative_evidence_order,&self.adversarial_event_order,&self.effect_receipts]{if !canonical(v){return Err(invalid("evidence set ordering is not canonical"));}}for v in [&self.study_digest_order,&self.artifact_digest_order]{if v.windows(2).any(|p|p[0]>=p[1]){return Err(invalid("evidence digest ordering is not canonical"));}}let ids=self.evidence_order.iter().collect::<BTreeSet<_>>();let parts=self.admitted_order.iter().chain(self.unresolved_order.iter()).chain(self.blocked_order.iter()).collect::<Vec<_>>();if parts.len()!=ids.len()||parts.iter().any(|x|!ids.contains(x))||parts.iter().collect::<BTreeSet<_>>().len()!=parts.len()||self.ranked_order.iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("evidence states do not partition observations"));}for d in [&self.replay_identity,&self.set_digest,&self.artifact.content_hash]{if !digest(d){return Err(invalid("evidence set digest is invalid"));}}self.artifact.validate_metadata().map_err(|e|EvidenceGatewayError::Artifact(e.to_string()))?;if self.artifact.content_type!=CONTENT_TYPE{return Err(invalid("evidence set artifact type is invalid"));}if self.disposition=="qualified"{if self.effect_receipts.len()!=1||self.effect_receipts[0]!=format!("exchange:permitted-artifacts:{}",self.request_id){return Err(invalid("qualified evidence exchange effect is invalid"));}}else if self.effect_receipts!=["block:unsafe-release"]{return Err(invalid("non-qualified evidence exchange must block release"));}Ok(())}}

pub fn integrate_evidence_feed(feed:&EvidenceFeed)->Result<QualifiedEvidenceSet,EvidenceGatewayError>{validate_feed(feed)?;let mut observations=feed.observations.clone();observations.sort_by(|a,b|b.relevance_milli.cmp(&a.relevance_milli).then(b.freshness_milli.cmp(&a.freshness_milli)).then(a.evidence_id.cmp(&b.evidence_id)));let ranked=observations.iter().map(|x|x.evidence_id.clone()).collect::<Vec<_>>();let mut order=ranked.clone();order.sort();let studies=feed.required_study_order.iter().cloned().collect::<BTreeSet<_>>();let modalities=feed.required_modality_order.iter().cloned().collect::<BTreeSet<_>>();let mut admitted=BTreeSet::new();let mut unresolved=BTreeSet::new();let mut blocked=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();let mut study_digests=BTreeSet::new();let mut artifact_digests=BTreeSet::new();for o in &observations{if o.negative_result{negative.insert(format!("{}:negative-result",o.evidence_id));}omissions.extend(o.omissions.iter().map(|x|format!("{}:{x}",o.evidence_id)));uncertainty.extend(o.uncertainty.iter().map(|x|format!("{}:{x}",o.evidence_id)));negative.extend(o.negative_evidence.iter().map(|x|format!("{}:{x}",o.evidence_id)));if o.state==EvidenceState::Contradicted{blocked.insert(o.evidence_id.clone());negative.insert(format!("{}:contradicted-evidence",o.evidence_id));continue;}if matches!(o.state,EvidenceState::Unknown|EvidenceState::Speculative){unresolved.insert(o.evidence_id.clone());uncertainty.insert(format!("{}:evidence-unresolved",o.evidence_id));continue;}let complete=studies.contains(&o.study_id)&&modalities.contains(&o.modality)&&o.relevance_milli>=600&&o.freshness_milli>=600&&o.semantic_digest.as_str().len()==64&&o.artifact_digest.as_str().len()==64&&o.provenance_digest.as_str().len()==64&&o.replay_identity==feed.replay_identity&&o.omissions.is_empty()&&o.uncertainty.is_empty()&&o.local_data&&o.permitted;if complete&&matches!(o.state,EvidenceState::Proven|EvidenceState::Supported){admitted.insert(o.evidence_id.clone());study_digests.insert(ContentHash::of_bytes(o.study_id.as_bytes()));artifact_digests.insert(o.artifact_digest.clone());}else{unresolved.insert(o.evidence_id.clone());if !studies.contains(&o.study_id){omissions.insert(format!("{}:required-study-missing",o.evidence_id));}if !modalities.contains(&o.modality){omissions.insert(format!("{}:required-modality-missing",o.evidence_id));}if o.relevance_milli<600{uncertainty.insert(format!("{}:relevance-threshold-not-met",o.evidence_id));}if o.freshness_milli<600{uncertainty.insert(format!("{}:freshness-threshold-not-met",o.evidence_id));}if !o.local_data||!o.permitted{blocked.insert(o.evidence_id.clone());unresolved.remove(&o.evidence_id);omissions.insert(format!("{}:locality-or-permission-denied",o.evidence_id));}}}let missing_study=feed.required_study_order.iter().filter(|s|!observations.iter().any(|o|&o.study_id==*s)).cloned().collect::<Vec<_>>();let missing_modality=feed.required_modality_order.iter().filter(|m|!observations.iter().any(|o|&o.modality==*m)).cloned().collect::<Vec<_>>();for s in &missing_study{omissions.insert(format!("required-study-missing:{s}"));}for m in &missing_modality{omissions.insert(format!("required-modality-missing:{m}"));}negative.extend(feed.adversarial_events.iter().map(|e|format!("adversarial:{e}")));let global=!feed.policy_allow||!feed.protected_closure||!feed.signed_approval||!feed.endpoint_approved||!feed.raw_data_local||!feed.aggregate_only||feed.budget>feed.max_budget||!feed.adversarial_events.is_empty();if !feed.policy_allow{uncertainty.insert("request:policy-denied".into());}if !feed.protected_closure{uncertainty.insert("request:protected-closure-incomplete".into());}if !feed.signed_approval||!feed.endpoint_approved{uncertainty.insert("request:endpoint-or-signature-approval-incomplete".into());}if feed.budget>feed.max_budget{omissions.insert("request:budget-ceiling-exceeded".into());}let disposition=if global{"blocked"}else if missing_study.is_empty()&&missing_modality.is_empty()&&!admitted.is_empty()&&unresolved.is_empty()&&blocked.is_empty(){"qualified"}else{"unresolved"};let admitted=admitted.into_iter().collect::<Vec<_>>();let unresolved=unresolved.into_iter().collect::<Vec<_>>();let blocked=blocked.into_iter().collect::<Vec<_>>();let omissions=omissions.into_iter().collect::<Vec<_>>();let uncertainty=uncertainty.into_iter().collect::<Vec<_>>();let negative=negative.into_iter().collect::<Vec<_>>();let study_order=study_digests.into_iter().collect::<Vec<_>>();let artifact_order=artifact_digests.into_iter().collect::<Vec<_>>();let effects=if disposition=="qualified"{vec![format!("exchange:permitted-artifacts:{}",feed.request_id)]}else{vec!["block:unsafe-release".into()]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":feed.request_id,"federation_id":feed.federation_id,"institution_id":feed.institution_id,"endpoint":feed.endpoint,"purpose":feed.purpose,"semantic_profile":feed.semantic_profile,"disposition":disposition,"evidence_order":order,"ranked_order":ranked,"admitted_order":admitted,"unresolved_order":unresolved,"blocked_order":blocked,"missing_study_order":missing_study,"missing_modality_order":missing_modality,"omission_order":omissions,"uncertainty_order":uncertainty,"negative_evidence_order":negative,"adversarial_event_order":feed.adversarial_events,"study_digest_order":study_order,"artifact_digest_order":artifact_order,"replay_identity":feed.replay_identity,"effect_receipts":effects,"raw_data_local":feed.raw_data_local,"aggregate_only":feed.aggregate_only,"boundary":PRECLINICAL_BOUNDARY});let set_digest=ContentHash::of_value(&payload).map_err(|e|EvidenceGatewayError::Artifact(e.to_string()))?;let artifact=TypedResearchArtifact::from_payload(format!("obligation-evidence-set:{}",feed.request_id),CONTENT_TYPE,&payload,Vec::new(),vec![ProvenanceLink{source_id:format!("endpoint:{}",feed.endpoint),relation:"derived-from-local-evidence-feed".into(),digest:feed.replay_identity.clone()}]).map_err(|e|EvidenceGatewayError::Artifact(e.to_string()))?;let out=QualifiedEvidenceSet{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:CONTRACT_VERSION.into(),feature_id:FEATURE_ID.into(),request_id:feed.request_id.clone(),federation_id:feed.federation_id.clone(),institution_id:feed.institution_id.clone(),endpoint:feed.endpoint.clone(),purpose:feed.purpose.clone(),semantic_profile:feed.semantic_profile.clone(),disposition:disposition.into(),evidence_order:order,ranked_order:ranked,admitted_order:admitted,unresolved_order:unresolved,blocked_order:blocked,missing_study_order:missing_study,missing_modality_order:missing_modality,omission_order:omissions,uncertainty_order:uncertainty,negative_evidence_order:negative,adversarial_event_order:feed.adversarial_events.clone(),study_digest_order:study_order,artifact_digest_order:artifact_order,replay_identity:feed.replay_identity.clone(),set_digest,artifact,effect_receipts:effects,raw_data_local:feed.raw_data_local,aggregate_only:feed.aggregate_only,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}

fn validate_feed(feed:&EvidenceFeed)->Result<(),EvidenceGatewayError>{if feed.request_id.trim().is_empty()||feed.federation_id.trim().is_empty()||feed.institution_id.trim().is_empty()||feed.endpoint.trim().is_empty()||feed.purpose.trim().is_empty()||feed.semantic_profile.trim().is_empty()||feed.required_study_order.is_empty()||feed.required_modality_order.is_empty()||feed.observations.is_empty()||!canonical(&feed.required_study_order)||!canonical(&feed.required_modality_order)||!canonical(&feed.adversarial_events)||!digest(&feed.replay_identity)||feed.budget==0||feed.max_budget==0||feed.boundary!=PRECLINICAL_BOUNDARY||!feed.raw_data_local||!feed.aggregate_only{return Err(invalid("evidence feed identity, closure, digest, budget, locality, or boundary is invalid"));}let mut ids=BTreeSet::new();for o in &feed.observations{if o.evidence_id.trim().is_empty()||o.source_id.trim().is_empty()||o.study_id.trim().is_empty()||o.modality.trim().is_empty()||o.scope.trim().is_empty()||!ids.insert(o.evidence_id.clone())||o.relevance_milli>1000||o.freshness_milli>1000||!digest(&o.semantic_digest)||!digest(&o.artifact_digest)||!digest(&o.provenance_digest)||!digest(&o.replay_identity)||!canonical(&o.omissions)||!canonical(&o.uncertainty)||!canonical(&o.negative_evidence){return Err(invalid(format!("observation {} is malformed or duplicated",o.evidence_id)));}}Ok(())}

#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn o(id:&str,state:EvidenceState,relevance:u16)->EvidenceObservation{EvidenceObservation{evidence_id:id.into(),source_id:format!("source:{id}"),study_id:"study-a".into(),modality:"imaging".into(),scope:"organoid".into(),relevance_milli:relevance,freshness_milli:900,state,semantic_digest:h(&format!("semantic:{id}")),artifact_digest:h(&format!("artifact:{id}")),provenance_digest:h(&format!("provenance:{id}")),replay_identity:h("replay"),omissions:vec![],uncertainty:vec![],negative_evidence:vec![],negative_result:false,local_data:true,permitted:true}}fn f(observations:Vec<EvidenceObservation>)->EvidenceFeed{EvidenceFeed{request_id:"request:evidence".into(),federation_id:"fed:commons".into(),institution_id:"site-a".into(),endpoint:"https://gateway.example".into(),purpose:"benchmarking".into(),semantic_profile:"preclinical-neural".into(),required_study_order:vec!["study-a".into()],required_modality_order:vec!["imaging".into()],observations,replay_identity:h("replay"),policy_allow:true,protected_closure:true,signed_approval:true,endpoint_approved:true,raw_data_local:true,aggregate_only:true,budget:8,max_budget:16,adversarial_events:vec![],boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn manifest_is_a2(){let m=evidence_gateway_manifest();m.validate().unwrap();assert_eq!(m.autonomy_tier,AutonomyTier::A2)}#[test]fn qualified_exchange(){let r=integrate_evidence_feed(&f(vec![o("evidence:a",EvidenceState::Supported,900)])).unwrap();assert_eq!(r.disposition,"qualified");assert!(r.effect_receipts[0].starts_with("exchange:permitted-artifacts:"))}#[test]fn stale_is_unresolved(){let mut x=f(vec![o("evidence:a",EvidenceState::Supported,500)]);x.observations[0].freshness_milli=500;let r=integrate_evidence_feed(&x).unwrap();assert_eq!(r.disposition,"unresolved");assert!(!r.uncertainty_order.is_empty())}#[test]fn unknown_and_contradicted_retained(){let r=integrate_evidence_feed(&f(vec![o("evidence:a",EvidenceState::Unknown,900),o("evidence:b",EvidenceState::Contradicted,900)])).unwrap();assert!(r.unresolved_order.contains(&"evidence:a".into()));assert!(r.blocked_order.contains(&"evidence:b".into()))}#[test]fn endpoint_denial_blocks(){let mut x=f(vec![o("evidence:a",EvidenceState::Supported,900)]);x.endpoint_approved=false;let r=integrate_evidence_feed(&x).unwrap();assert_eq!(r.disposition,"blocked")}#[test]fn duplicate_rejected(){let x=f(vec![o("evidence:a",EvidenceState::Supported,900),o("evidence:a",EvidenceState::Supported,900)]);assert!(integrate_evidence_feed(&x).is_err())}#[test]fn deterministic(){let a=integrate_evidence_feed(&f(vec![o("evidence:b",EvidenceState::Supported,800),o("evidence:a",EvidenceState::Supported,900)])).unwrap();let b=integrate_evidence_feed(&f(vec![o("evidence:a",EvidenceState::Supported,900),o("evidence:b",EvidenceState::Supported,800)])).unwrap();assert_eq!(a.ranked_order,b.ranked_order);assert_eq!(a.set_digest,b.set_digest)}}
